SELECT 'pet-cronograma-legendas-202611-leg-criancas-25', '[TESTE] Encontro com as crianças', '<p>Teste do cronograma de postagens — Semana 4 de novembro/2026.</p><p>Definir o formato da postagem.</p><p>Postagem prevista: 25/11/2026.</p><p>Responsável indicado no cronograma: Andreza.</p><p>Vinculada somente à comissão Legendas; não aparece na Visão geral.</p>', '', '2026-11-25', '[]', '["legendas"]', '{}', '[{"id":"cronograma-18-postagem","label":"Postagem","dueAt":"2026-11-25T23:59:00","assigneeIds":[],"completedAt":null}]', 'pendente', NULL, a.id, a.id, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, '{}', 0, 'comissoes'
FROM users a WHERE a.id=(SELECT id FROM users WHERE role='admin' ORDER BY created_at LIMIT 1)
AND EXISTS (SELECT 1 FROM commissions WHERE id='legendas');

